@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + socialSecurityNumber : string
  + name : string
  + emailAddress : string
}

class ResearchStaff extends Employee {
  + fieldOfResearch : string
}

class AdministrativeStaff extends Employee {}

class ResearchAssistant extends ResearchStaff {
}

class Lecturer extends ResearchAssistant {
}

class Project {
  + name : string
  + startDate : date
  + endDate : date
  + hours : int
}

class Course {
  + ID : int
  + name : string
  + weeklyDuration : int
}

Faculty "1" -- "1..*" Institute : consists of
Faculty "1" -- "0..1" Employee : headed by
Institute "1" -- "1..*" ResearchAssistant : has
ResearchAssistant "1" -- "*" Project : involved in
Lecturer "1" -- "*" Course : teaches

@enduml

